#include <bits/stdc++.h>
using namespace std;

int main() {
    int N, M;
    cin >> N >> M;

    vector<int> a(N), costs;
    for (int &v : a) cin >> v;

    int odd = 0, even = 0;

    for (int i = 0; i < N - 1; ++i) {
        if (a[i] % 2)
            ++odd;
        else
            ++even;

        if (odd == even)
            costs.push_back(abs(a[i] - a[i + 1]));
    }

    sort(costs.begin(), costs.end());

    int answer = 0;
    for (int cost : costs) {
        if (cost > M) break;
        M -= cost;
        ++answer;
    }

    cout << answer;
    return 0;
}

